import re
p='.skilled/skills/sk-doc/sk-create-quality-control/references/transformation-patterns.md'
lines=open(p).read().splitlines()
open_fence=None
for i,l in enumerate(lines,1):
    m=re.match(r'^(`{3,})(.*)$',l)
    if not m: continue
    ticks, info=m.group(1),m.group(2)
    if open_fence is None:
        open_fence=(len(ticks),i,info)
        print(f'{i:3}: OPEN {len(ticks)} {info!r}')
    else:
        if len(ticks)>=open_fence[0] and not info.strip():
            print(f'{i:3}: CLOSE (opened {open_fence[1]} at {open_fence[0]})')
            open_fence=None
        else:
            print(f'{i:3}: nested/inner {len(ticks)} {info!r} (open {open_fence[1]}/{open_fence[0]})')
print('unclosed:',open_fence)
